$users=db()->query('SELECT id,username,full_name,role,is_active,created_at FROM users ORDER BY id DESC LIMIT 200')->fetchAll();$pageTitle='Isticmaalayaasha';require __DIR__.'/../includes/header.php';
?><div class="page-toolbar"><div><h1>Isticmaalayaasha</h1><p class="muted">Admin-ku wuxuu abuuraa oo maamulaa akoonnada.</p></div></div><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><?php if($success): ?><div class="alert success"><?=e($success)?></div><?php endif; ?><div class="content-grid users-grid"><section class="panel"><div class="panel-heading"><h3>Akoon cusub</h3></div><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Magaca oo buuxa<input name="full_name" required></label><label>Username<input name="username" required autocomplete="off"></label><label>Erayga sirta ah<input type="password" name="password" minlength="10" required autocomplete="new-password"><small>Ugu yaraan 10 xaraf; isticmaal xarfo waaweyn, yaryar, tirooyin iyo calaamado.</small></label><label>Doorka<select name="role"><option value="teacher">Macallin</option><option value="parent">Waalid</option><option value="cashier">Cashier</option><option value="student">Arday</option><option value="admin">Admin</option></select></label><button class="btn primary">Abuur akoon</button></form></section><section class="panel"><div class="panel-heading"><h3>Akoonno jira</h3></div><div class="table-wrap"><table><thead><tr><th>Magac</th><th>Username</th><th>Doorka</th><th>Xaalad</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['username'])?></td><td><?=e($u['role'])?></td><td><span class="status <?= $u['is_active']?'active':'inactive' ?>"><?=$u['is_active']?'Firfircoon':'Xiran'?></span></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php'; ?>
